//=============================================================================
//  M1 modification (2026-10-21) -- the ONLY change to a vendor file in this
//  project:  AF 128 --> 256.
//
//  AF is the absolute FIFO level at which afull_flag asserts (UG301 sec 14.3:
//  default AF = DATA_DEPTH_W-6, i.e. an absolute used count).  With the vendor
//  value of 128 the read port keeps only ~128 words of look-ahead.  That is
//  enough for the vendor single read port at 33 MHz, but M1 runs TWO read
//  ports (page A + page B) plus one write port through the same controller and
//  RD2 is the lowest priority one: the 100 MHz burst model
//  (sim/model_sdram_fb.py) shows the RD2 FIFO dropping to 24 words (~1 us)
//  with AF=128, i.e. no margin against one extra burst of arbitration delay.
//  With AF=256 the FIFO keeps 256..383 words: the model then reports 152
//  words (6.1 us) minimum, and still 99 words when every burst costs 3x the
//  RTL-derived value.  A 128 word burst added to at most 255 words used can
//  never overflow a 512 deep FIFO.
//=============================================================================
`timescale 1ns / 1ps

module Sdram_RD_FIFO (
	rst,
	di, clkw, we,
	do, clkr, re,
	empty_flag,
	full_flag, afull_flag 
);

	input rst;
	input [31:0] di;
	input clkw, we;
	input clkr,re;

	output [31:0] do;
	output empty_flag;
	output full_flag, afull_flag;

EG_LOGIC_FIFO #(
 	.DATA_WIDTH_W(32),
	.DATA_WIDTH_R(32),
	.DATA_DEPTH_W(512),
	.DATA_DEPTH_R(512),
	.ENDIAN("BIG"),
	.RESETMODE("ASYNC"),
